pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address player, uint256 count) public {
        // bound number of plays to keep it feasible but wide (1..10 plays)
        count = bound(count, 1, 10);
        vm.assume(player != address(0));

        uint256 expectedPot = 0;
        bool lastWasWin = false;
        uint256 potAfterLastWin = 0;

        // simulate `count` plays, tracking expected pot under reference semantics
        for (uint256 i = 0; i < count; i++) {
            vm.deal(player, 10);
            vm.prank(player);
            try c.play{value: 10}() {
                // determine outcome by checking pot after call
                uint256 potAfter = c.pot();
                if (potAfter == 0) {
                    // reset observed -> win occurred
                    lastWasWin = true;
                    potAfterLastWin = potAfter;
                    expectedPot = 0;
                } else {
                    lastWasWin = false;
                    expectedPot = expectedPot + 10; // only fee taken, pot grows
                }
            } catch {
                // ignore revert (value mismatch) – won't happen with vm.deal
            }
        }

        // The invariant: for the correct contract, pot is always exactly the sum of ticket amounts not yet paid
        // In the mutant, pot is never reset after a win, so after at least one win, pot > 0 even though it should be 0.
        // We assert: if the last play was a win, pot must be 0.
        if (lastWasWin) {
            assertEq(c.pot(), 0, "pot must be 0 after a win in reference; mutant leaves stale balance");
        }
    }
}

