import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint8 numPlays) public {
        // Bound numPlays to a reasonable range to avoid timeout but keep it wide
        numPlays = uint8(bound(numPlays, 1, 10));

        // Give the caller enough ether for all plays
        uint256 totalEther = uint256(numPlays) * 10;
        vm.deal(address(this), totalEther);

        // Play numPlays times, using seed to determine if each play wins (we cannot control random directly,
        // but we can observe the state after each call)
        for (uint8 i = 0; i < numPlays; i++) {
            // Try to call play; if it reverts due to random condition not met, we still advance the state observation
            // but we need to handle the case where play doesn't revert (random==0), which changes pot.
            // We simply call play and let the internal random decide.
            c.play{value: 10}();
        }

        // The invariant: contract balance == pot + bank balance (bank is address(c).balance of bank? No, bank is an address.
        // bank balance is address(c.bank()).balance. The contract's balance is address(c).balance.
        // After any sequence of plays, since no external withdrawals except through wins,
        // the sum of pot and the bank's balance should equal the contract's balance.
        uint256 contractBalance = address(c).balance;
        uint256 bankBalance = c.bank().balance;
        uint256 pot = c.pot();
        // The contract holds pot and bank fees that haven't been transferred yet? Actually, bank is an external address,
        // so bank's balance is not part of contract balance. Let's reconsider:
        // Contract holds all ticket amounts. When someone wins, contract transfers FEE_AMOUNT to bank and pot-FEE_AMOUNT to winner.
        // The pot is supposed to represent the amount accumulated from tickets not yet paid out.
        // In the correct contract, after a win, pot is reset to 0. So pot reflects the amount that has been contributed
        // but not yet distributed. The contract balance should equal pot because no funds are held for any other purpose.
        // bank is an external address, so fees are sent out. Thus: contract balance == pot.
        // The mutant fails to reset pot after a win, so contract balance < pot after a win.
        assertTrue(contractBalance == pot, "Invariant violated: contract balance must equal pot");
    }
}

