pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint8 numPlays) public {
        // numPlays bounded to a reasonable range to ensure test runs fast, but wide enough to include at least 2 plays
        uint256 plays = bound(numPlays, 2, 10);
        address player1 = address(uint160(uint256(keccak256(abi.encode(seed, "player1")))));
        address player2 = address(uint160(uint256(keccak256(abi.encode(seed, "player2")))));
        // Ensure players are distinct and not the bank
        vm.assume(player1 != player2 && player1 != c.bank() && player2 != c.bank());
        vm.assume(player1 != address(0) && player2 != address(0));

        vm.deal(player1, 100 ether);
        vm.deal(player2, 100 ether);

        // First play by player1 - always a loser (random % 2 is predictable, but we cannot control it directly)
        // Since we cannot control randomness, we need to ensure the test covers the scenario where a win occurs before a second play.
        // We'll rely on repeated plays with the same players to increase probability of hitting a win followed by another play.
        // However, the property we check does not depend on randomness: we check that after any sequence of plays,
        // pot is always 0 or TICKET_AMOUNT (which is 10). The reference guarantees pot is 0 after a win, and TICKET_AMOUNT after a single loss or after a win followed by a loss, but the mutant can accumulate pot beyond TICKET_AMOUNT.
        // We'll execute `plays` number of plays alternating players, then check that pot is either 0 or exactly TICKET_AMOUNT.
        // The mutant can have pot = 2*TICKET_AMOUNT or more, breaking the invariant.

        for (uint256 i = 0; i < plays; i++) {
            address currentPlayer = (i % 2 == 0) ? player1 : player2;
            vm.prank(currentPlayer);
            c.play{value: 10 wei}();
        }

        uint256 currentPot = c.pot();
        bool validPot = (currentPot == 0) || (currentPot == 10);
        assertTrue(validPot);
    }
}

