import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed1, uint256 seed2) public {
        // We need at least two consecutive plays; first play may or may not trigger a payout.
        // We use two different block.timestamp values via vm.warp to get different random outcomes.
        // Admissible domain: any two timestamps > 0, spaced apart (must not revert due to same block).
        vm.assume(seed1 > 0 && seed2 > 0);
        vm.assume(seed1 != seed2);

        // Give some Ether to an actor and play first round.
        address player = makeAddr("player");
        vm.deal(player, 20 ether);
        vm.prank(player);
        vm.warp(seed1);
        c.play{value: 10 ether}();

        uint potAfterFirst = c.pot();

        // If pot is already zero, the invariant is trivially satisfied after a second round that triggers a payout.
        // To test the bug, we need a scenario where pot becomes non-zero (first play did not trigger a payout),
        // then a second play triggers a payout (under modulo 2), but the buggy version fails to reset pot.
        // This happens when: first random % 2 != 0 (no payout), pot = 10;
        // second random % 2 == 0 but % 3 != 0 (payout in reference, no payout in bug).
        // The fuzzer will search for such a pair.

        // Second play
        vm.prank(player);
        vm.warp(seed2);
        c.play{value: 10 ether}();

        uint potAfterSecond = c.pot();

        // Invariant: If pot after first round was non-zero, and the second round's random outcome
        // would have been a win under the reference (mod 2), then pot must be zero after second round.
        // We simulate the reference outcome for the second round without modifying state.
        uint random2 = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        // Note: block.timestamp is seed2 after warp, block.difficulty is still original.

        if (potAfterFirst != 0 && random2 == 0) {
            assertTrue(potAfterSecond == 0);
        }
    }
}

