        bool shouldPlay = fuzz % 2 == 0;

        // We can call play multiple times; each call requires exactly TICKET_AMOUNT = 10 wei
        // We need an actor with enough balance
        address player = address(0x1234);
        vm.deal(player, 100 ether);

        if (shouldPlay) {
            vm.prank(player);
            c.play{value: 10}();
        }

